 const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

+// --- Assistive technology announcements (#302) ------------------------------
+// An innerHTML replacement is silent to assistive technology, so results are
+// mirrored into the polite live region above: nothing is interrupted, the
+// message lands after the paint, and every figure in it is one the engine
+// produced — read straight off the served document, never derived here. An
+// undetermined state is announced as exactly that: unknown, not failure.
+const announce = (message) => {
+  const region = $('out-status');
+  if (!region) return;
+  // Clearing first makes an identical message re-announce.
+  region.textContent = '';
+  window.setTimeout(() => { region.textContent = message; }, 50);
+};
+
+// One announcement for a measurement document: the integrity state the
+// engine issued, the finding in the engine's own words, then the
+// recommendation or its explicit absence.
+const announceResult = (d) => {
+  const send = (d.send_asset && d.send_asset.code) || '';
+  const recv = (d.receive_asset && d.receive_asset.code) || '';
+  const corridor = [send, recv].filter(Boolean).join(' → ');
+  if (d.recommended) {
+    announce(`${corridor}: ${d.integrity}. ${d.finding} Recommended at ` +
+      `${d.recommended_size} ${send}: ${d.recommended.loss_pct}% below mid, ` +
+      `graded ${d.recommended.verdict}.`);
+  } else if (d.scored) {
+    announce(`${corridor}: ${d.integrity}. ${d.finding} No size tested is worth taking.`);
+  } else {
+    announce(`${corridor}: no verdict could be issued. ${d.finding}`);
+  }
+};
+
+// Same for the trend view: the window and the latest state, read off the
+// stored runs.
+const announceTrend = (d) => {
+  const runs = d.runs || [];
+  if (runs.length === 0) {
+    announce(`No stored runs for the ${d.corridor} corridor yet.`);
+    return;
+  }
+  const latest = runs[runs.length - 1];
+  announce(`Trend for the ${d.corridor} corridor: ${runs.length} stored ` +
+    `run${runs.length === 1 ? '' : 's'} from ${fmtRunTime(runs[0].recorded_at)} ` +
+    `to ${fmtRunTime(latest.recorded_at)} UTC. Latest integrity ${latest.integrity}.`);
+};
+
